  $(this).fadeTo(500,1);
}&quot; ONMOUSEOVER=&quot;this.src = &#39;/images/pathfinder/wiki/ialt.png&#39;;&quot;
ONMOUSEOUT=&quot;this.src = &#39;/images/pathfinder/wiki/ibase.png&#39;;&quot; /&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;/table&gt;&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des joueurs - Classes avanc&#233;es (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Class Guide/Manuel des joueurs - Classes avanc&#233;es&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoMCA.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;b&gt;Les pouvoirs de rage du sang.&lt;/b&gt; Les pouvoirs de rage du sang conf&#232;rent des pouvoirs th&#233;matiques. Ceux choisis par un barbare ne peuvent provenir que d’un seul groupe. Un barbare, quel que soit son niveau, peut prendre un pouvoir mineur de rage du sang. Seuls les barbares de niveau 6 ou plus peuvent choisir le pouvoir interm&#233;diaire de rage du sang (un pouvoir dont le nom ne comporte ni &#171; mineur &#187; ni &#171; majeur &#187;) s’ils poss&#232;dent d&#233;j&#224; le pouvoir mineur du m&#234;me groupe. Seuls les barbares de niveau 10 ou plus peuvent choisir le pouvoir sup&#233;rieur de rage du sang s’ils poss&#232;dent d&#233;j&#224; le pouvoir interm&#233;diaire du m&#234;me groupe.&lt;br /&gt;&lt;br /&gt;
&lt;table CLASS=&quot;tablo toutgauche centre autoalt&quot; WIDTH=&quot;96%&quot;&gt;&lt;caption&gt;Pouvoirs de rage du barbare unchained&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;Niveau&lt;br /&gt;minimal&lt;/td&gt;&lt;td COLSPAN=&quot;4&quot;&gt;Pouvoirs de rage&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;b&gt;1&lt;/b&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Rage-Unchained.html#ANIMALTOTEMMINEUR&quot; title=&quot;Pouvoirs de rage du barbare unchained&quot;&gt;Animal totem, mineur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Rage-Unchained.html#IVRESSERUGISSANTE&quot; title=&quot;Pouvoirs de rage du barbare unchained&quot;&gt;Ivresse rugissante&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Rage-Unchained.html#POSTUREPRECISE&quot; title=&quot;Pouvoirs de rage du barbare unchained&quot;&gt;Posture pr&#233;cise&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Rage-Unchained.html#SANGINFERNALMINEUR&quot; title=&quot;Pouvoirs de rage du barbare unchained&quot;&gt;Sang infernal mineur&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Rage-Unchained.html#AVANCEDOMINATRICE&quot; title=&quot;Pouvoirs de rage du barbare unchained&quot;&gt;Avance dominatrice&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Rage-Unchained.html#LUCIDITEPARFAITE&quot; title=&quot;Pouvoirs de rage du barbare unchained&quot;&gt;Lucidit&#233; parfaite&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Rage-Unchained.html#POSTUREPUISSANTE&quot; title=&quot;Pouvoirs de rage du barbare unchained&quot;&gt;Posture puissante&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Rage-Unchained.html#SAUTENRAGE&quot; title=&quot;Pouvoirs de rage du barbare unchained&quot;&gt;Saut en rage&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Rage-Unchained.html#BAGARREUR&quot; title=&quot;Pouvoirs de rage du barbare unchained&quot;&gt;Bagarreur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Rage-Unchained.html#MARQUEPROMETTEUSE&quot; title=&quot;Pouvoirs de rage du barbare unchained&quot;&gt;Marque prometteuse&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Rage-Unchained.html#POURSUITE&quot; title=&quot;Pouvoirs de rage du barbare unchained&quot;&gt;Poursuite&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Rage-Unchained.html#SUPERSTITION&quot; title=&quot;Pouvoirs de rage du barbare unchained&quot;&gt;Superstition&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Rage-Unchained.html#BAGARREURMAJEUR&quot; title=&quot;Pouvoirs de rage du barbare unchained&quot;&gt;Bagarreur majeur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Rage-Unchained.html#MONTUREFEROCE&quot; title=&quot;Pouvoirs de rage du barbare unchained&quot;&gt;Monture f&#233;roce&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Rage-Unchained.html#PROJECTILEMINEUR&quot; title=&quot;Pouvoirs de rage du barbare unchained&quot;&gt;Projectile mineur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Rage-Unchained.html#TOTEMDUCHAOSMINEUR&quot; title=&quot;Pouvoirs de rage du barbare unchained&quot;&gt;Totem du chaos, mineur&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Rage-Unchained.html#BONPOURCEQUETUAS&quot; title=&quot;Pouvoirs de rage du barbare unchained&quot;&gt;Bon pour ce que tu as&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Rage-Unchained.html#NAGEENRAGE&quot; title=&quot;Pouvoirs de rage du barbare unchained&quot;&gt;Nage en rage&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Rage-Unchained.html#REFELEXESRAPIDES&quot; title=&quot;Pouvoirs de rage du barbare unchained&quot;&gt;R&#233;flexes rapides&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Rage-Unchained.html#TOTEMDUSERPENTMONDE&quot; title=&quot;Pouvoirs de rage du barbare unchained&quot;&gt;Totem du serpent-monde&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Rage-Unchained.html#BUVEURPRODIGIEUX&quot; title=&quot;Pouvoirs de rage du barbare unchained&quot;&gt;Buveur prodigieux&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Rage-Unchained.html#ODORAT&quot; title=&quot;Pouvoirs de rage du barbare unchained&quot;&gt;Odorat&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Rage-Unchained.html#REGARDINTIMIDANT&quot; title=&quot;Pouvoirs de rage du barbare unchained&quot;&gt;Regard intimidant&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Rage-Unchained.html#TOTEMFIELONMINEUR&quot; title=&quot;Pouvoirs de rage du barbare unchained&quot;&gt;Totem fi&#233;lon, mineur&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Rage-Unchained.html#CHASSEURDESORCIERE&quot; title=&quot;Pouvoirs de rage du barbare unchained&quot;&gt;Chasseur de sorci&#232;re&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Rage-Unchained.html#OUSTE&quot; title=&quot;Pouvoirs de rage du barbare unchained&quot;&gt;Ouste&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Rage-Unchained.html#REPOUSSERLENNEMI&quot; title=&quot;Pouvoirs de rage du barbare unchained&quot;&gt;Repousser l’ennemi&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Rage-Unchained.html#TOTEMSPIRITUELMINEUR&quot; title=&quot;Pouvoirs de rage du barbare unchained&quot;&gt;Totem spirituel, mineur&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Rage-Unchained.html#COLEREAUTOSUGGEREE&quot; title=&quot;Pouvoirs de rage du barbare unchained&quot;&gt;Col&#232;re autosugg&#233;r&#233;e&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Rage-Unchained.html#PASRAPIDES&quot; title=&quot;Pouvoirs de rage du barbare unchained&quot;&gt;Pas rapides&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Rage-Unchained.html#RESISTANCEALENERGIE&quot; title=&quot;Pouvoirs de rage du barbare unchained&quot;&gt;R&#233;sistance &#224; l’&#233;nergie&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Rage-Unchained.html#VIEPRESERVEE&quot; title=&quot;Pouvoirs de rage du barbare unchained&quot;&gt;Vie pr&#233;serv&#233;e&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Rage-Unchained.html#COURAGELIQUIDE&quot; title=&quot;Pouvoirs de rage du barbare unchained&quot;&gt;Courage liquide&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Rage-Unchained.html#POSTUREDEFENSIVE&quot; title=&quot;Pouvoirs de rage du barbare unchained&quot;&gt;Posture d&#233;fensive&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Rage-Unchained.html#SANGCELESTEMINEUR&quot; title=&quot;Pouvoirs de rage du barbare unchained&quot;&gt;Sang c&#233;leste mineur&lt;/a&g