&lt;h3 class=&quot;separator&quot;&gt;Bagarreur majeur&lt;a class=&quot;headeranchor&quot; id=&quot;Bagarreur_majeur_7&quot; href=&quot;#Bagarreur_majeur_7&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&lt;b&gt;Pr&#233;requis&lt;/b&gt; : &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Rage-Unchained.html#BAGARREUR&quot; title=&quot;Pouvoirs de rage du barbare unchained&quot;&gt;Bagarreur&lt;/a&gt;&lt;br /&gt;&lt;br /&gt;Lorsqu’il est en &lt;a class=&quot;pagelink&quot; href=&quot;Barbare-Unchained.html#RAGEDEBERSERKER&quot; title=&quot;Le barbare unchained&quot;&gt;rage&lt;/a&gt;, le barbare b&#233;n&#233;ficie du don &lt;a class=&quot;pagelink&quot; href=&quot;Combat-&#192;-Deux-Armes.html&quot; title=&quot;Combat &#224; deux armes&quot;&gt;Combat &#224; deux armes&lt;/a&gt; quand il porte des attaques &#224; mains nues.&lt;br /&gt;&lt;br /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des joueurs - R&#232;gles avanc&#233;es (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
